package io.mac2phone.app;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.security.*;
public class NearbyTests {
 @Test public void singleUseExpiryQuotaAndRevocation(){long[] now={0};ConnectionGrants grants=new ConnectionGrants(()->now[0]);byte[] token=grants.issue();assertTrue(grants.consume(token));assertFalse(grants.consume(token));token=grants.issue();now[0]=60000;assertFalse(grants.consume(token));for(int i=0;i<8;i++)grants.issue();try{grants.issue();fail();}catch(IllegalStateException expected){}grants.clear();assertEquals(32,grants.issue().length);}
 @Test public void approvalPairingRoundTrip(){Pairing p=Pairing.generate("127.0.0.1",8765);p.ticket=new byte[32];assertEquals(p.link(),Pairing.parse(p.link()).link());assertArrayEquals(p.ticket,Pairing.parse(p.link()).ticket);try{Pairing.parse(p.link().replace("#v3.","#v2."));fail();}catch(IllegalArgumentException expected){}}
 @Test public void agreementEncryptionAndTamper()throws Exception{NearbyCrypto a=new NearbyCrypto(),b=new NearbyCrypto();a.agree("Tablet","android",a.publicKey,b.publicKey);b.agree("Tablet","android",a.publicKey,b.publicKey);assertArrayEquals(a.key,b.key);assertEquals(a.code,b.code);String encrypted=a.seal("{\"status\":\"declined\"}");assertEquals("{\"status\":\"declined\"}",b.open(encrypted));byte[] bytes=Base64.getDecoder().decode(encrypted);bytes[15]^=1;try{b.open(Base64.getEncoder().encodeToString(bytes));fail();}catch(javax.crypto.AEADBadTagException expected){}a.close();b.close();}
 @Test public void commitmentBindsKeyAndNonce()throws Exception{NearbyCrypto a=new NearbyCrypto(),b=new NearbyCrypto();byte[] nonce=NearbyCrypto.nonce();String commit=NearbyCrypto.commit(a.publicKey,nonce);assertNotEquals(commit,NearbyCrypto.commit(b.publicKey,nonce));nonce[0]^=1;assertNotEquals(commit,NearbyCrypto.commit(a.publicKey,nonce));}
 @Test public void rejectsAmbiguousNames(){assertFalse(NearbyCrypto.validName("evil\u202e"));assertFalse(NearbyCrypto.validName("\n"));assertTrue(NearbyCrypto.validName("My Android"));}
}
